// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1
        c.SetMinSum(1);
        // Set LogFile to any non-zero address (e.g., address(this))
        c.SetLogFile(address(this));
        // Initialize to lock further changes in reference
        c.Initialized();

        // Fund an account with 1 ether and let it put with lock time 0
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 1}(0); // balance=1, unlockTime = block.timestamp

        // Warp past unlockTime
        vm.warp(block.timestamp + 1);

        // Now call Collect(0) from user; this should succeed in reference
        vm.prank(user);
        c.Collect(0);

        // In reference, MinSum should remain 1 (unchanged).
        // In bug, SetMinSum inside Collect (mutated) sets MinSum to 0.
        assertTrue(c.MinSum() == 1);
    }
}

