contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        uint256 lockTime = 100;
        uint256 amount = 1 ether;

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Alice puts 1 ether with lockTime=100 at block.timestamp = 1000
        vm.warp(1000);
        vm.deal(alice, amount);
        vm.prank(alice);
        c.Put{value: amount}(lockTime);

        // Warp past unlockTime
        vm.warp(2000);

        // Alice collects 1 ether
        vm.prank(alice);
        c.Collect(amount);

        // In the reference, unlockTime is set to block.timestamp+lockTime = 2000+100 = 2100
        // In the bug, the condition (block.timestamp+lockTime < acc.unlockTime) is false (2100 < 2100 is false),
        // so unlockTime remains 2100 from before? Actually after Collect, unlockTime is not changed by Collect.
        // The divergence: in the reference, after Put, unlockTime = 1100; after Collect, it stays 1100.
        // In the bug, after Put, unlockTime = 1000+100 = 1100; after Collect, it stays 1100.
        // This scenario does not work.

        // Actually the difference is in Put: reference sets unlockTime = block.timestamp+_lockTime when condition holds,
        // bug sets it only when block.timestamp+_lockTime < acc.unlockTime. So if acc.unlockTime is 0 initially,
        // the bug will NOT set it (since 1100 < 0 is false), while the reference will (since 1100 > 0).
        // So we need to read unlockTime AFTER Put but BEFORE any further call that might change it.
        // Let's test after Put, not after Collect.

        // Re-initialize with a fresh contract deployed in setUp() to avoid leftover state
        // Actually setUp() runs before each test, so it's fresh.

        // Simpler: just call Put once and read unlockTime immediately.
        vm.warp(1000);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.Put{value: 1 wei}(lockTime);

        // Reference: unlockTime = 1000+100 = 1100
        // Bug: condition 1100 < 0 is false, so unlockTime stays 0
        (uint256 unlockTime, uint256 balance) = c.Acc(alice);

        // The reference has unlockTime > 0, the bug has unlockTime == 0
        assertTrue(unlockTime > 0);
    }
}

